using System.IO;
using UnityEditor;
using UnityEngine;

namespace CatBattleground
{
    /// <summary>
    /// Import rules + materials for the arena art kit (Assets/Art/Arena, generated by Tools/ArenaKit).
    /// Textures: small, crunch-compressed, foliage cards keep their alpha edge when mip-mapped.
    /// Models: materials are mapped by name to Assets/Art/Arena/Materials/&lt;name&gt;.mat.
    /// </summary>
    public class ArenaAssetPostprocessor : AssetPostprocessor
    {
        public const string TexDir = "Assets/Art/Arena/Textures/";
        public const string ModelDir = "Assets/Art/Arena/Models/";
        public const string MatDir = "Assets/Art/Arena/Materials/";

        void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(TexDir) || !(assetImporter is TextureImporter ti)) return;
            var name = Path.GetFileNameWithoutExtension(assetPath);
            bool card = ArenaAssets.IsCard(name);
            ti.textureType = TextureImporterType.Default;
            ti.sRGBTexture = true;
            ti.alphaIsTransparency = card;
            ti.mipmapEnabled = true;
            ti.mipMapsPreserveCoverage = card;      // keeps leaf clusters from thinning out at a distance
            ti.alphaTestReferenceValue = 0.5f;
            ti.wrapMode = card ? TextureWrapMode.Clamp : TextureWrapMode.Repeat;
            ti.filterMode = FilterMode.Bilinear;
            ti.maxTextureSize = 256;
            ti.crunchedCompression = true;
            ti.compressionQuality = 55;
        }

        void OnPreprocessModel()
        {
            if (!assetPath.StartsWith(ModelDir) || !(assetImporter is ModelImporter mi)) return;
            var name = Path.GetFileNameWithoutExtension(assetPath);
            mi.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
            mi.importNormals = ModelImporterNormals.Import;
            mi.importBlendShapes = false;
            mi.importCameras = false;
            mi.importLights = false;
            mi.isReadable = ArenaAssets.NeedsCollider(name);   // MeshColliders are made from these meshes
            mi.meshCompression = ModelImporterMeshCompression.Off;
        }

        Material OnAssignMaterialModel(Material material, Renderer renderer)
        {
            if (!assetPath.StartsWith(ModelDir)) return null;
            return AssetDatabase.LoadAssetAtPath<Material>(MatDir + material.name + ".mat");
        }
    }

    public static class ArenaAssets
    {
        static readonly string[] CardPrefixes = { "leaf_", "pine_frond", "fern", "grass_green", "grass_gold", "flower_" };
        static readonly string[] ColliderPrefixes = { "house_", "ruin_", "barracks", "watchtower", "tent", "sandbag", "crate", "barrel", "fence", "rock_", "log_", "stump_", "flag" };

        public static bool IsCard(string textureName)
        {
            foreach (var p in CardPrefixes) if (textureName.StartsWith(p)) return true;
            return false;
        }

        public static bool NeedsCollider(string modelName)
        {
            foreach (var p in ColliderPrefixes) if (modelName.StartsWith(p)) return true;
            return false;
        }

        /// <summary>Refresh imports, build the materials, then re-import the models so they pick the materials up by name.</summary>
        public static void Prepare()
        {
            AssetDatabase.Refresh();
            BuildMaterials();
            foreach (var path in Directory.GetFiles("Assets/Art/Arena/Models", "*.obj"))
                AssetDatabase.ImportAsset(path.Replace('\\', '/'), ImportAssetOptions.ForceUpdate);
            AssetDatabase.SaveAssets();
        }

        static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            var parent = Path.GetDirectoryName(path).Replace('\\', '/');
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
        }

        static void BuildMaterials()
        {
            EnsureFolder("Assets/Art/Arena/Materials");
            foreach (var path in Directory.GetFiles("Assets/Art/Arena/Textures", "*.png"))
            {
                var name = Path.GetFileNameWithoutExtension(path);
                if (name == "grass_tile" || name == "dirt_tile") continue;   // only used to paint the terrain texture
                var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path.Replace('\\', '/'));
                if (texture == null) continue;

                var matPath = ArenaAssetPostprocessor.MatDir + name + ".mat";
                var mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
                if (mat == null)
                {
                    mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                    AssetDatabase.CreateAsset(mat, matPath);
                }
                mat.SetTexture("_BaseMap", texture);
                mat.SetColor("_BaseColor", Color.white);
                mat.SetFloat("_Smoothness", 0.04f);
                mat.SetFloat("_Metallic", 0f);

                bool card = IsCard(name);
                mat.SetFloat("_AlphaClip", card ? 1f : 0f);
                mat.SetFloat("_Cutoff", 0.5f);
                mat.SetFloat("_Cull", card ? 0f : 2f);            // foliage is two-sided
                if (card) mat.EnableKeyword("_ALPHATEST_ON"); else mat.DisableKeyword("_ALPHATEST_ON");
                mat.SetOverrideTag("RenderType", card ? "TransparentCutout" : "Opaque");
                mat.renderQueue = card ? (int)UnityEngine.Rendering.RenderQueue.AlphaTest : -1;
                EditorUtility.SetDirty(mat);
            }
            AssetDatabase.SaveAssets();
        }

        public static GameObject Model(string name) => AssetDatabase.LoadAssetAtPath<GameObject>(ArenaAssetPostprocessor.ModelDir + name + ".obj");
        public static Material Material(string name) => AssetDatabase.LoadAssetAtPath<Material>(ArenaAssetPostprocessor.MatDir + name + ".mat");
    }
}
